"""Render node layers from features.yaml and nodes/<node>/node.yaml.

(no args)          write nodes/<node>/<layer>/kustomization.yaml and nodes/<node>/data/services/<svc>.yaml
--check            fail if anything is invalid or a generated file is out of date (CI)
--dropped <root>   list stateful data present in the tree at <root> (e.g. the target branch) but gone here
YAML is read through $YQ (a yq command printing JSON; set by the justfile).
"""
import json, os, pathlib, shlex, subprocess, sys

PLATFORM_LAYERS = ["infrastructure", "operators"]
FEATURE_LAYERS = ["data", "apps"]
# Service need -> template rendered into the service's file (needs are also features of the same name).
NEEDS = {"postgres": "bootstrap/database.yaml.tpl", "rabbitmq": "bootstrap/rabbitmq-user.yaml.tpl"}
HEADER = "# Generated by `just features` from node.yaml and features.yaml. Do not edit.\n"


def load(root, path):
    r = subprocess.run([*shlex.split(os.environ.get("YQ", "yq")), "-o=json", "."],
                       input=path.read_text(), capture_output=True, text=True)
    if r.returncode:
        sys.exit(f"error: {path.relative_to(root)}: {r.stderr.strip()}")
    return json.loads(r.stdout)


def evaluate(root):
    """(rendered files {path: text or None to delete}, stateful data {node: set}, errors) of the tree at root."""
    errors, rendered, stateful = [], {}, {}
    if not (root / "features.yaml").exists():
        return rendered, stateful, errors
    catalog = load(root, root / "features.yaml")
    platform_cfg, components = catalog.get("platform", {}), catalog.get("components", {})
    features, services = catalog.get("features", {}), catalog.get("services", {})

    platform = [c for layer in PLATFORM_LAYERS for c in platform_cfg.get(layer, [])]
    for layer in platform_cfg:
        if layer not in PLATFORM_LAYERS:
            errors.append(f"platform: layer {layer!r} is not one of {PLATFORM_LAYERS}")
    for c, layer in components.items():
        if layer not in FEATURE_LAYERS:
            errors.append(f"component {c}: layer {layer!r} is not one of {FEATURE_LAYERS} (providers belong to platform)")
        if c in platform:
            errors.append(f"component {c}: both platform and feature-toggled")
    for c in [*platform, *components]:
        if not (root / "components" / c / "kustomization.yaml").is_file():
            errors.append(f"component {c}: components/{c}/kustomization.yaml missing")
    for c in catalog.get("stateful", []):
        if c not in components:
            errors.append(f"stateful: {c!r} is not a feature-toggled component")
    for s, spec in services.items():
        for need in spec.get("needs", []):
            if need not in NEEDS:
                errors.append(f"service {s}: unknown need {need!r} (one of {list(NEEDS)})")

    def resolve(items, where):
        enabled, deps, svcs = set(), set(), set()

        def visit(item, stack):
            ctx = f" (in feature {stack[-1]})" if stack else ""
            if item.startswith("dep:"):
                if item[4:] not in components:
                    errors.append(f"{where}: unknown component {item[4:]!r}{ctx}")
                deps.add(item[4:])
            elif item.startswith("svc:"):
                if item[4:] not in services:
                    errors.append(f"{where}: unknown service {item[4:]!r}{ctx}")
                elif item[4:] not in svcs:
                    svcs.add(item[4:])
                    for need in services[item[4:]].get("needs", []):
                        visit(need, stack + (item,))
            elif item in stack:
                errors.append(f"{where}: feature cycle {' -> '.join(stack + (item,))}")
            elif item not in features:
                errors.append(f"{where}: unknown feature {item!r}{ctx}")
            elif item not in enabled:
                enabled.add(item)
                for x in features[item]:
                    visit(x, stack + (item,))

        for i in items:
            visit(i, ())
        return enabled, deps, svcs

    def service_file(name):
        docs = [(root / NEEDS[n]).read_text().replace("${NAME}", name).replace("${PG}", name.replace("-", "_"))
                for n in NEEDS if n in services[name].get("needs", [])]
        return HEADER + "---\n".join(docs)

    for node_yaml in sorted((root / "nodes").glob("*/node.yaml")):
        node_dir, where = node_yaml.parent, node_yaml.parent.name
        enabled, deps, svcs = resolve(load(root, node_yaml).get("features", []), where)
        stateful[where] = {f"{c} cluster" for c in deps if c in catalog.get("stateful", [])}
        stateful[where] |= {f"{s} database" for s in svcs if "postgres" in services[s].get("needs", [])}
        layers = {layer: list(platform_cfg.get(layer, [])) for layer in PLATFORM_LAYERS}
        layers |= {layer: [c for c, l in components.items() if l == layer and c in deps] for layer in FEATURE_LAYERS}
        for layer, on in layers.items():
            d = node_dir / layer
            resources, patches = [f"../../../components/{c}" for c in on], []
            for c in on:
                version = d / f"{c}.version.yaml"
                if version.exists():
                    patches.append(version.name)
                elif any("# per node" in p.read_text() for p in (root / "components" / c).glob("*.yaml")):
                    errors.append(f"{where}: component {c} needs {version.relative_to(root)}")
            for version in sorted(d.glob("*.version.yaml")):
                if version.name.removesuffix(".version.yaml") not in on:
                    errors.append(f"{where}: {version.relative_to(root)} is for a disabled component; delete it")
            if layer == "data":
                for s in sorted(svcs):
                    rendered[d / "services" / f"{s}.yaml"] = service_file(s)
                    resources.append(f"services/{s}.yaml")
                for old in (d / "services").glob("*.yaml"):
                    if old.stem not in svcs:
                        rendered[old] = None
            body = HEADER + "apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\n"
            body += "resources:" + ("".join(f"\n  - {r}" for r in resources) if resources else " []") + "\n"
            if patches:
                body += "patches:" + "".join(f"\n  - path: {p}" for p in patches) + "\n"
            rendered[d / "kustomization.yaml"] = body
        items = sorted(enabled) + [f"svc:{s}" for s in sorted(svcs)]
        print(f"{where}: {', '.join(items) or '(platform only)'}", file=sys.stderr)
    return rendered, stateful, errors


root = pathlib.Path(__file__).resolve().parent.parent
rendered, stateful, errors = evaluate(root)
if errors:
    sys.exit("\n".join(f"error: {e}" for e in errors))

if "--dropped" in sys.argv:
    _, base, base_errors = evaluate(pathlib.Path(sys.argv[sys.argv.index("--dropped") + 1]).resolve())
    if base_errors:
        print(f"warning: base tree has errors; comparing what it renders: {base_errors[0]}", file=sys.stderr)
    for node, items in sorted(base.items()):
        for item in sorted(items - stateful.get(node, set())):
            print(f"{node}: {item}")
    sys.exit(0)

check = "--check" in sys.argv
stale = [p for p, body in rendered.items() if (p.read_text() if p.exists() else None) != body]
for p in stale:
    if check:
        print(f"out of date: {p.relative_to(root)} (run: just features)")
    elif rendered[p] is None:
        p.unlink()
        print(f"deleted {p.relative_to(root)}")
    else:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(rendered[p])
        print(f"wrote {p.relative_to(root)}")
sys.exit(1 if check and stale else 0)
